questionvariables.text:
cardn(S) := length(listify(S));
dset(S) := if emptyp(S) then "\\{\\,\\}" else sconcat("\\{", simplode(map(string, listify(S)), ", "), "\\}");
ix: 1+rand(10);
cls(k) := [[1, is(k=1), "empty"], [2, is(k=2), "finite, not empty"], [3, is(k=3), "infinite"]];
/* Design: classify sets as empty, finite or infinite. Source: adapted from SMP Book 1, revision exercise, page 126, question 6.
   Curated list: each entry one empty, one finite and one infinite set; order varies.
   k: key (1 empty, 2 finite, 3 infinite); w: a wrong option for tests; e: the explanation. */
L: [["\\{x : x \\text{ is a natural number}, x + 7 = 7\\}","\\{x : x \\text{ is a whole number}, x + 7 = 7\\}","\\{x : x \\text{ is a multiple of 7}\\}","\\(x + 7 = 7\\) gives \\(x = 0\\), which is not a natural number, so the set is empty.","\\(x = 0\\) is a whole number, so the set is \\(\\{0\\}\\): finite, not empty.","\\(7, 14, 21, \\ldots\\) go on for ever: infinite.",1,2,3,2,3,1],
  ["\\{\\text{the grains in a 90 kg bag of maize}\\}","\\{x : x \\text{ is an integer}, x < 3\\}","\\{x : x \\text{ is an even prime number greater than 2}\\}","A \\(90\\) kg bag holds a very large but countable number of grains: finite.","\\(2, 1, 0, -1, -2, \\ldots\\) go on for ever: infinite.","The only even prime number is \\(2\\), so no even prime is greater than \\(2\\): the set is empty.",2,3,1,3,1,2],
  ["\\{x : x \\text{ is an odd number greater than 1000}\\}","\\{x : x \\text{ is a whole number}, 2x = 9\\}","\\{x : x \\text{ is a factor of 1\\,000\\,000}\\}","\\(1001, 1003, 1005, \\ldots\\) go on for ever: infinite.","\\(2x = 9\\) gives \\(x = 4.5\\), which is not a whole number, so the set is empty.","A number has only a limited number of factors, none bigger than itself: finite.",3,1,2,1,2,3],
  ["\\{\\text{the months of the year with fewer than 28 days}\\}","\\{x : x \\text{ is a fraction between 0 and 1}\\}","\\{\\text{the learners in all the schools in Kenya today}\\}","Every month has at least \\(28\\) days, so the set is empty.","Between any two fractions there is another one: infinite.","There are millions of them, but they could be counted: finite.",1,3,2,2,1,3],
  ["\\{x : x \\text{ is an integer}, -1000 < x < 1000\\}","\\{x : x \\text{ is an integer}, 4 < x < 5\\}","\\{x : x \\text{ is a square number}\\}","These are the integers from \\(-999\\) to \\(999\\), which is \\(1999\\) elements: finite.","There is no integer between \\(4\\) and \\(5\\), so the set is empty.","\\(1, 4, 9, 16, \\ldots\\) go on for ever: infinite.",2,1,3,3,2,1],
  ["\\{x : x \\text{ is a multiple of 3 that is also even}\\}","\\{x : x \\text{ is a prime number less than 1000}\\}","\\{x : x \\text{ is a natural number}, x < 1\\}","\\(6, 12, 18, \\ldots\\) go on for ever: infinite.","Only numbers below \\(1000\\) can belong, so there are fewer than \\(1000\\) elements: finite.","The natural numbers start at \\(1\\), so none is less than \\(1\\): the set is empty.",3,2,1,1,3,2],
  ["\\{x : x \\text{ is a multiple of 10 whose last digit is 5}\\}","\\{x : x \\text{ is a square number between 50 and 70}\\}","\\{x : x \\text{ is a negative integer}\\}","Every multiple of \\(10\\) ends in \\(0\\), so the set is empty.","\\(64\\) is the only one, so the set is \\(\\{64\\}\\): finite.","\\(-1, -2, -3, \\ldots\\) go on for ever: infinite.",1,2,3,2,3,1],
  ["\\{x : x \\text{ is a natural number}, x^2 < 200\\}","\\{x : x \\text{ is a decimal number between 1 and 2}\\}","\\{x : x \\text{ is a square number between 50 and 60}\\}","\\(14^2 = 196\\) and \\(15^2 = 225\\), so the set is \\(\\{1, 2, \\ldots, 14\\}\\): finite.","\\(1.1, 1.01, 1.001, \\ldots\\) never come to an end: infinite.","\\(7^2 = 49\\) and \\(8^2 = 64\\), so no square number lies between \\(50\\) and \\(60\\): the set is empty.",2,3,1,3,1,2],
  ["\\{x : x \\text{ is a whole number whose last digit is 3}\\}","\\{x : x \\text{ is a prime number that is a multiple of 6}\\}","\\{x : x \\text{ is a three-digit whole number}\\}","\\(3, 13, 23, \\ldots\\) go on for ever: infinite.","A multiple of \\(6\\) has the factors \\(2\\) and \\(3\\), so it is not prime: the set is empty.","These are the numbers from \\(100\\) to \\(999\\), which is \\(900\\) elements: finite.",3,1,2,1,2,3],
  ["\\{x : x \\text{ is a whole number}, x + 3 = 1\\}","\\{x : x \\text{ is a multiple of 100}\\}","\\{\\text{the words in this textbook}\\}","\\(x + 3 = 1\\) gives \\(x = -2\\), which is not a whole number, so the set is empty.","\\(100, 200, 300, \\ldots\\) go on for ever: infinite.","A book has a very large but limited number of words: finite.",1,3,2,2,1,3]];
d1: L[ix][1]; d2: L[ix][2]; d3: L[ix][3]; e1: L[ix][4]; e2: L[ix][5]; e3: L[ix][6]; k1: L[ix][7]; k2: L[ix][8]; k3: L[ix][9]; w1: L[ix][10]; w2: L[ix][11]; w3: L[ix][12]; 
o1: cls(k1); o2: cls(k2); o3: cls(k3);
